#include <iostream>
using namespace std;

template <typename T>
T bigger(T a, T b) {
    return a > b ? a : b;
}

int main() {
    int n = 0;
    cin >> n;

    int best = 0;
    double bestD = 0.0;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        best = bigger(best, x);
        bestD = bigger(bestD, x + 0.5);
    }

    cout << best << endl;
    cout << bestD << endl;
    return 0;
}
